<script setup lang="ts">
import { ref, watch } from "vue";
import { ApiError, item, request, query, type SchedulePolicy, type AutomationSchedule, type AutomationRevision, type Page } from "@papilio/api";
import { useAuth } from "@papilio/auth";
import { faDate, faNumber } from "@papilio/ui";
import NumField from "@papilio/ui/NumField.vue";
import {useI18n} from "vue-i18n";
const props = defineProps<{ schedule: AutomationSchedule; title: string }>();
const emit = defineEmits<{ changed: [AutomationSchedule] }>();
const auth = useAuth(); const {t}=useI18n(); const current = ref<AutomationSchedule|null>(null); const draft = ref<SchedulePolicy|null>(null);
const interval = ref(""); const batch = ref(""); const recheck = ref(""); const reason = ref(""); const busy = ref(false); const error = ref(""); const notice = ref("");
const history = ref<AutomationRevision[]>([]); const historyState = ref<"loading"|"ready"|"error">("loading"); const page = ref(1); const pages = ref(1); let version = 0;
function values(row: AutomationSchedule): SchedulePolicy { return { mode: row.mode, interval_seconds: row.interval_seconds, enabled: row.enabled, cron: row.cron, timezone: row.timezone, batch_size: row.batch_size, recheck_seconds: row.recheck_seconds }; }
function reset(row: AutomationSchedule): void { current.value = row; draft.value = values(row); interval.value = row.interval_seconds === null ? "" : String(row.interval_seconds); batch.value = String(row.batch_size); recheck.value = row.recheck_seconds === null ? "" : String(row.recheck_seconds); }
async function loadHistory(): Promise<void> { const key = props.schedule.key; const generation = version; const selectedPage = page.value; historyState.value = "loading"; try { const result = await request<Page<AutomationRevision>>(`/v1/admin/automation/schedules/${key}/history?${query({page: selectedPage})}`); if (generation !== version || page.value !== selectedPage) return; history.value = result.data; pages.value = result.meta.pager?.total_pages ?? 1; historyState.value = "ready"; } catch(cause) { if (generation !== version) return; historyState.value = "error"; error.value = cause instanceof Error ? cause.message : "The operation failed. Please try again."; } }
watch(() => props.schedule.key, () => { version++; reset(props.schedule); reason.value = ""; error.value = ""; notice.value = ""; page.value = 1; history.value = []; void loadHistory(); }, {immediate: true});
async function reload(): Promise<void> { const key = props.schedule.key; const generation = version; busy.value = true; error.value = ""; try { const row = await item<AutomationSchedule>(`/v1/admin/automation/schedules/${key}`); if (generation !== version) return; reset(row); emit("changed", row); await loadHistory(); } catch(cause) { if (generation === version) error.value = cause instanceof Error ? cause.message : "The operation failed. Please try again."; } finally { busy.value = false; } }
async function save(): Promise<void> {
 if (!current.value || !draft.value || busy.value) return; const key = current.value.key; const generation = version; busy.value = true; error.value = ""; notice.value = "";
 try { const row = await item<AutomationSchedule>(`/v1/admin/automation/schedules/${key}`, "PUT", { expected_revision: current.value.revision, reason: reason.value.trim(), values: {...draft.value, interval_seconds: draft.value.mode === "interval" ? Number(interval.value) : null, cron: draft.value.mode === "cron" ? draft.value.cron : null, timezone: draft.value.mode === "cron" ? draft.value.timezone : null, batch_size: Number(batch.value), recheck_seconds: current.value.recheck_seconds === null ? null : Number(recheck.value)} }); if (generation !== version) return; reset(row); reason.value = ""; emit("changed", row); notice.value = t("automation.scheduleEditor.saved"); page.value = 1; await loadHistory(); }
 catch(cause) { if (generation !== version) return; error.value = cause instanceof Error ? cause.message : "The operation failed. Please try again."; if (cause instanceof ApiError && cause.code === "automation_revision_conflict") { try { const row = await item<AutomationSchedule>(`/v1/admin/automation/schedules/${key}`); if (generation !== version) return; current.value = row; emit("changed", row); error.value += ` ${t("automation.scheduleEditor.conflict")}`; } catch(refreshError) { error.value = refreshError instanceof Error ? refreshError.message : t("automation.scheduleEditor.refreshError"); } } }
 finally { busy.value = false; }
}
async function reconcile(): Promise<void> { if (!current.value || busy.value) return; busy.value = true; error.value = ""; try { await request(`/v1/admin/automation/schedules/${current.value.key}/reconcile`, "POST"); notice.value = t("automation.scheduleEditor.queued"); } catch(cause) { error.value = cause instanceof Error ? cause.message : "The operation failed. Please try again."; } finally { busy.value = false; } }
</script>
<template><section class="card card-pad"><h2>{{t('automation.scheduleEditor.title',{title})}}</h2><p v-if="error" class="message error" role="alert">{{ error }}</p><p v-if="notice" class="message" role="status">{{ notice }}</p><template v-if="current"><p v-if="!current.capacity_valid" class="message error">{{t('automation.scheduleEditor.capacity')}}</p><p>{{t('settingsForm.revision')}} {{ faNumber(current.revision) }} · {{ current.applied_revision === current.revision ? t('automation.scheduleEditor.registered') : t('automation.scheduleEditor.awaiting') }} · {{ current.registered_at ? faDate(current.registered_at) : t('automation.scheduleEditor.notReconciled') }}</p><p>{{t('automation.scheduleEditor.effect')}}</p><button class="btn secondary" :disabled="busy" @click="reload">{{t('automation.scheduleEditor.refresh')}}</button><form v-if="draft" class="form-grid" @submit.prevent="save"><fieldset :disabled="busy || !auth.can('settings','update')"><label class="check-row"><input v-model="draft.enabled" type="checkbox" />{{t('automation.scheduleEditor.enable')}}</label><label class="field"><span>{{t('automation.scheduleEditor.mode')}}</span><select v-model="draft.mode"><option value="cron">{{t('automation.scheduleEditor.cron')}}</option><option value="interval">{{t('automation.scheduleEditor.interval')}}</option></select></label><NumField v-if="draft.mode === 'interval'" v-model="interval" :label="t('automation.scheduleEditor.runInterval')" /><label v-if="draft.mode === 'cron'" class="field"><span>{{t('automation.scheduleEditor.expression')}}</span><input v-model="draft.cron" required dir="ltr" /><small>{{t('automation.scheduleEditor.cronHint')}}</small></label><label v-if="draft.mode === 'cron'" class="field"><span>{{t('automation.scheduleEditor.timezone')}}</span><input v-model="draft.timezone" required dir="ltr" placeholder="Asia/Tehran" /></label><NumField v-model="batch" :label="t('automation.scheduleEditor.batch')" /><NumField v-if="current.recheck_seconds !== null" v-model="recheck" :label="t('automation.scheduleEditor.recheck')" /><label class="field"><span>{{t('automation.scheduleEditor.reason')}}</span><textarea v-model="reason" required minlength="3" maxlength="250" /></label><button v-if="auth.can('settings','update')" class="btn" :disabled="busy || reason.trim().length < 3 || Number(batch) < 1">{{t('automation.scheduleEditor.save')}}</button></fieldset></form><button v-if="auth.can('settings','update')" class="btn secondary" :disabled="busy" @click="reconcile">{{t('automation.scheduleEditor.reconcile')}}</button></template><h3>{{t('automation.scheduleEditor.history')}}</h3><p v-if="historyState === 'loading'">{{t('automation.scheduleEditor.loading')}}</p><p v-else-if="historyState === 'error'">{{t('automation.scheduleEditor.historyError')}}</p><p v-else-if="!history.length">{{t('automation.scheduleEditor.initial')}}</p><details v-for="row in history" :key="row.revision"><summary>{{t('settingsForm.revision')}} {{ faNumber(row.revision) }} · {{ faDate(row.created_at) }} · {{t('automation.scheduleEditor.operator')}} {{ faNumber(row.staff_id) }}</summary><p>{{ row.reason }}</p><p>{{ row.values.enabled ? t('automation.scheduleEditor.active') : t('automation.scheduleEditor.paused') }} · {{ row.values.timezone }}</p><p v-if="row.values.mode === 'cron'" dir="ltr" class="mono">{{ row.values.cron }}</p><p v-else>{{t('automation.scheduleEditor.every',{seconds:faNumber(row.values.interval_seconds ?? 0)})}}</p><p>{{t('automation.scheduleEditor.capacityLabel')}} {{ faNumber(row.values.batch_size) }} · {{ row.values.recheck_seconds === null ? t('automation.scheduleEditor.noRecheck') : t('automation.scheduleEditor.every',{seconds:faNumber(row.values.recheck_seconds)}) }}</p></details><div class="pager"><button :disabled="page <= 1" @click="page--; loadHistory()">‹</button><span>{{t('automation.scheduleEditor.pages',{page:faNumber(page),pages:faNumber(pages)})}}</span><button :disabled="page >= pages" @click="page++; loadHistory()">›</button></div></section></template>
<style scoped>fieldset { display: grid; gap: 14px; border: 0; padding: 0; margin: 0; min-inline-size: 0; }</style>
